SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0610000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 61, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "61", "printedPageNumber": 61, "pdfPageNumber": 444, "sequenceIndex": 51, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0610100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "REPROACH ON GIVING UP JAMAAT", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0610200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith I", "sourceIdentifier": "I", "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0610000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "CHAPTER II", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 61"}, {"id": "f0610100-0000-4000-8000-000000000001", "structuralNodeId": "b0610100-0000-4000-8000-000000000001", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "REPROACH ON GIVING UP JAMAAT", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 61"}, {"id": "f0610200-0000-4000-8000-000000000001", "structuralNodeId": "b0610100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Just as Allah has promised rewards and blessings for adhering to His commandments, so has He warned us of the woeful consequences and punishments for their neglect. We are in bondage to Allah and as such it is obligatory on us to obey Him. No compensation or reward is due to us for our obedience to Him. If He gives a reward, it is surely a matter of His extreme favour on us. Similarly no punishments can be too much for us if we disobey Him—our Lord, for there can be no greater crime for a bondsman than to disobey his Master. Hence no warning or premonition was required to be imparted. Yet Allah and His Holy Prophet (Sallallaho alaihe wasallam) have so very kindly cautioned us in various ways, warned us frequently of the consequences and explained to us again and again, just to save us from disaster. If even then, we don''t take a lesson, who could there be to save us from the inevitable consequences?", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 61"}, {"id": "f0610300-0000-4000-8000-000000000001", "structuralNodeId": "b0610200-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith I", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 61"}, {"id": "f0610400-0000-4000-8000-000000000001", "structuralNodeId": "b0610200-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن ابن عباس رضي الله عنه قال قال رسول الله ﷺ من سمع النداء فلم يمنعه من اتباعه عذر قالوا وما العذر قال خوف أو مرض لم تقبل منه الصلاة التي صلى رواه أبو داود وابن حبان في صحيحه وابن ماجه نحوه", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 61"}, {"id": "f0610500-0000-4000-8000-000000000001", "structuralNodeId": "b0610200-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Ibn Abbas (Radhiyallaho anho) narrates, \"I heard the Prophet (Sallallaho alaihe wasallam) saying, ''If a person in spite of hearing the Azaan does not go to the musjid (and he prefers to say his salaat at home) without a strong excuse, then his salaat is not accepted.'' When the Companions inquired as to what could be a strong excuse, he replied, ''Illness or fear.''\"\n\nIt may perhaps appear from this Hadith that the salaat performed at home (after hearing the Azaan) is no salaat at all; the Hanafiyyah do not hold this view. According to them, though the reward and blessings promised for fardh salaat will not be awarded, yet the person saying the salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 61"}]}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0620000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 62, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "62", "printedPageNumber": 62, "pdfPageNumber": 445, "sequenceIndex": 52, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0620100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith II", "sourceIdentifier": "II", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0620000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 62"}, {"id": "f0620100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "at his place does absolve himself of the obligation. But in the opinion of some of the companions and their successors, salaat with jamaat (after hearing the Azaan) is fardh and its discard is haraam. According to many other theologians, such a person is not even absolved of the obligation in respect of salaat of that hour. Anyhow, he is surely committing the sin of discarding jamaat. In another hadith narrated by Hadhrat Ibn Abbas, it is stated that such a person is guilty of disobedience of Allah and His Apostle (Sallallaho alaihe wasallam). Hadhrat Ibn Abbas (Radhiyallaho anho) also says, \"No good is done by, nor any good is done to, the person who does not join jamaat after hearing the Azaan.\" Hadhrat Abu Hurairah (Radhiyallaho anho) says, \"It is more appropriate to pour molten-lead into the ears of a person who does not go to join jamaat.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 62"}, {"id": "f0620200-0000-4000-8000-000000000001", "structuralNodeId": "b0620100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith II", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 62"}, {"id": "f0620300-0000-4000-8000-000000000001", "structuralNodeId": "b0620100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "قال العلماء كل من سمع النداء فلم يجب فلا صلاة له وقال ﷺ بحسب المؤمن من الشقاء والخيبة أن يسمع المؤذن يثوب بالصلاة فلا يجيبه رواه الطبراني عن معاذ بن أنس كذا في الكنز", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 62"}, {"id": "f0620400-0000-4000-8000-000000000001", "structuralNodeId": "b0620100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Mu''aaz bin Anas (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"A person who does not go for salaat after hearing the Azaan is committing a great wrong and is doing an act of kufr and nifaaq.\"\n\nAccording to this hadith, not to join jamaat after hearing the Azaan is not becoming of a Muslim and is the practice of a kaafir or a munaafiq. What a strong reproof!\n\nIn another hadith, it is said, \"Not to join jamaat after hearing the Azaan is sufficient to render a person most unfortunate and most wretched.\"\n\nHadhrat Sulaimaan bin Abi Hathmah (Radhiyallaho anho) is one of the eminent people of the early days of Islam. He was born during the lifetime of the Prophet (Sallallaho alaihe wasallam), but was too young then to have had the honour of listening to any hadith from him. During the Caliphate of Hadhrat Umar (Radhiyallaho anho) he was made in charge of the market. One day Hadhrat Umar (Radhiyallaho anho) found him missing in Fajr salaat. Hadhrat Umar (Radhiyallaho anho) went to his house and inquired from his mother why Sulaimaan was not present in Fajr. She replied, \"He kept saying nafl salaat throughout the", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 62"}]}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0630000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 63, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "63", "printedPageNumber": 63, "pdfPageNumber": 446, "sequenceIndex": 53, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0630100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith III", "sourceIdentifier": "III", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0630000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part II (b)—Reproach on Discard of Jamaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 63"}, {"id": "f0630100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "night, and sleep overpowered him at the time of Fajr.\" At this, Hadhrat Umar (Radhiyallaho anho) remarked, \"I would prefer my Fajr with jamaat to my offering nafl salaat all night long.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 63"}, {"id": "f0630200-0000-4000-8000-000000000001", "structuralNodeId": "b0630100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith III", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 63"}, {"id": "f0630300-0000-4000-8000-000000000001", "structuralNodeId": "b0630100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن أبي هريرة رضي الله عنه قال قال رسول الله ﷺ لقد هممت أن آمر فتيتي فيجمعوا حزماً من حطب ثم آتي قوماً يصلون في بيوتهم ليست بهم علة فأحرقها عليهم رواه أبو داود وابن ماجه", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 63"}, {"id": "f0630400-0000-4000-8000-000000000001", "structuralNodeId": "b0630100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu Hurairah (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"I wish I could ask the boys to collect a huge quantity of firewood for me, and then, I would go around and set fire to the dwellings of those who say their salaat at their own houses without any excuse.\"\n\nThe Prophet (Sallallaho alaihe wasallam), who was most kind and merciful towards his followers and was greatly pained to see them even in a little trouble, gets offended so much that he is ready to set fire to the houses of those who are content with saying salaat at their houses.\n\nHadhrat Abu Darda (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"If there are (even) three persons in a village or in a desert, and they do not say their salaat with jamaat, then Satan gets hold of them. Remember that jamaat for salaat is very necessary for you. Surely a wolf devours a lonely sheep, and Satan is the wolf for men.\"\n\nThis shows that people busy in farming etc. should arrange to say their salaat with jamaat if they are three or more in number. Even if they are two, it is better to have", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 63"}]}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0640000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 64, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "64", "printedPageNumber": 64, "pdfPageNumber": 447, "sequenceIndex": 54, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0640100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith V", "sourceIdentifier": "V", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0640000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 64"}, {"id": "f0640100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "jamaat. The farmers in our country are generally negligent of salaat and consider their occupation a sufficient excuse for their neglect, and even those who are considered pious prefer to perform their salaat individually. If the farmers working in the nearby fields get together at a place and perform prayers in jamaat, they can have quite a big gathering and thereby receive the wonderful blessings of Allah. Notwithstanding the sun, rain, heat and cold, they keep busy for a trifling worldly gain, but lose tremendous amount of Allah''s reward by losing salaat. On the other hand, they can earn a reward fifty times more (as conveyed in another hadith) by offering their salaat with jamaat in the fields.\n\nIt is stated in a hadith, \"When a shepherd calls out the Azaan at the foot of a hill (or in the fields) and starts his salaat, Allah is greatly pleased with him and says proudly to the Angels, ''Behold My slave! He has called out the Azaan and is offering his salaat. All this he does out of fear for Me. I therefore grant him forgiveness and declare his admittance into Paradise.''\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 64"}, {"id": "f0640200-0000-4000-8000-000000000001", "structuralNodeId": "b0640100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith V", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 64"}, {"id": "f0640300-0000-4000-8000-000000000001", "structuralNodeId": "b0640100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن ابن عباس رضي الله عنهما أنه سئل عن رجل يصوم النهار ويقوم الليل ولا يشهد الجمعة ولا الجماعة قال هو في النار رواه الترمذي", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 64"}, {"id": "f0640400-0000-4000-8000-000000000001", "structuralNodeId": "b0640100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Somebody asked Ibn Abbas (Radhiyallaho anho), \"What about a person who keeps fast all day and offers nafl salaat all night, but does not go to the musjid for jamaat and Jumu''ah?\" \"He is doomed to Hell\", replied Hadhrat Ibn Abbas (Radhiyallaho anho).\n\nSuch a person, being a Muslim, may ultimately get freedom from Hell, but who knows after how long. The ignorant among the Soofis and Shaikhs are very particular about Zikr and nafl salaat and consider this an act of eminence in piety, while they are not particular about salaat with jamaat. It must be clearly borne in mind for all times that no person can achieve religious eminence except through complete adherence to the practices of the beloved Prophet (Sallallaho alaihe wasallam).\n\nIt is stated in a hadith that Allah curses three persons: An Imaam who insists on leading the people of a place in salaat, although they do not like him on some reasonable account, a woman who is under the displeasure of her hus-", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 64"}]}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0650000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 65, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "65", "printedPageNumber": 65, "pdfPageNumber": 448, "sequenceIndex": 55, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0650100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith—VI", "sourceIdentifier": "VI", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0650000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part II (b)—Reproach on Discard of Jamaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}, {"id": "f0650100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "band; and a person who hears the Azaan but does not go to the musjid for salaat with Jamaat.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}, {"id": "f0650200-0000-4000-8000-000000000001", "structuralNodeId": "b0650100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith—VI", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}, {"id": "f0650300-0000-4000-8000-000000000001", "structuralNodeId": "b0650100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "أخرج ابن مردويه عن كعب الحبر قال والذي أنزل التوراة على موسى والإنجيل على عيسى والزبور على داود والفرقان على محمد أنزلت هذه الآيات في الصلوات المكتوبات حيث ينادى بهن يوم يكشف عن ساق إلى قوله وهم سالمون، الصلوات الخمس إذا نودي بها وأخرج البيهقي في الشعب عن سعيد بن جبير قال الصلوات في الجماعات وأخرج البيهقي عن ابن عباس قال رجل يسمع الأذان فلا يجيب الصلاة كذا في الدر المنثور قلت وقام الآية يوم يكشف عن ساق ويدعون إلى السجود فلا يستطيعون خاشعة أبصارهم ترهقهم ذلة وقد كانوا يدعون إلى السجود وهم سالمون", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}, {"id": "f0650400-0000-4000-8000-000000000001", "structuralNodeId": "b0650100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Ka''b Ahbaar says, \"By Him who revealed the Torah to Moosa, the Injeel to Eesa, the Psalms to Dawood (Alayhimus salaam), and the Qur''an on Muhammad (Sallallaho alaihe wasallam), the following verses were revealed in respect of saying fardh salaat in those places (mosques) where the Azaan is said: \"On the day when the glory of Saaq is revealed and they are ordered to prostrate themselves, but are not able, with eyes downcast, abasement stupifying them. And they had been summoned to prostrate themselves when they were quite hale and healthy.\" (LXVIII: 42 and 43).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}, {"id": "f0650500-0000-4000-8000-000000000001", "structuralNodeId": "b0650100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "The glory of Saaq is a particular type of glory to be displayed on the Day of Judgement. All Muslims will fall prostrate on seeing this glory, but there will be some whose backs will turn stiff and they will be unable to prostrate themselves. As to who these unlucky persons would be, different interpretations have been given by different commentators. According to this hadith, which is also corroborated by another narrated by Hadhrat Ibn Abbas (Radhiyallaho anho), those shall be the persons who were called for salaat with jamaat, but did not go for it.\n\nA few other interpretations of the same are given below:—\n\n1. Hadhrat Abu Sa''eed Khudri (Radhiyallaho anho) narrates on the authority of the Prophet (Sallallaho alaihe wasallam) that these shall be the persons who used to offer their salaat to be seen by other men.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}]}'::jsonb);